pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize creating bins with too much unused space
    if bin_capacity - bin_residual > 50 {
        score -= (bin_capacity - bin_residual - 50) as f64 * 0.01;
    }

    // Reward filling bins completely
    if post_residual == 0 {
        score += 1.0;
    }

    // Penalize opening new bins
    score -= open_bins_count as f64 * 0.02;

    // Reward fitting items into existing bins
    if fitting_bins_count > 0 {
        score += (fitting_bins_count as f64 / open_bins_count as f64) * 0.1;
    }

    // Penalize large item sizes that don't fit well
    if next_item_size > bin_residual + post_residual && fitting_bins_count == 0 {
        score -= (next_item_size - (bin_residual + post_residual)) as f64 * 0.2;
    }

    // Reward using bins efficiently based on mean residual
    if mean_residual < 50 {
        score += (50.0 - mean_residual) as f64 * 0.1;
    } else if mean_residual > 75 {
        score -= (mean_residual - 75.0) as f64 * 0.2;
    }

    // Penalize near the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= (progress - 0.9) * 5.0;
    }

    score
}

