pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize creating bins that are likely to be underutilized
    if bin_residual > item_size * 2 {
        score += (bin_residual - item_size * 2) as f64;
    }

    // Reward bins that can fit the next item without exceeding capacity
    if next_item_size != 0 && post_residual >= next_item_size {
        score -= 3.0 / (post_residual as f64 + 1.0);
    }

    // Penalize opening new bins when possible
    if fitting_bins_count > 2 {
        score += (fitting_bins_count - 2) as f64 * 2.0;
    }

    // Reward maintaining low mean residual across open bins
    if mean_residual < bin_capacity / 3.0 {
        score -= mean_residual / (bin_capacity / 3.0);
    } else {
        score += (mean_residual - bin_capacity / 3.0) * 2.5;
    }

    // Penalize items that are too large to fit in the current bin
    if item_size > bin_residual {
        score += (item_size - bin_residual) as f64 * 15.0;
    }

    // Reward bins with high capacity utilization
    if post_residual < bin_capacity / 4.0 {
        score -= post_residual as f64 / (bin_capacity / 4.0);
    } else if post_residual > bin_capacity * 3 / 4.0 {
        score += (post_residual - bin_capacity * 3 / 4.0) as f64 * 2.0;
    }

    // Penalize bins that are nearly full
    if bin_residual < 15 {
        score += bin_residual as f64;
    }

    // Reward the end of the stream to close any remaining open bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 && open_bins_count > 0 {
        score -= open_bins_count as f64 * 30.0;
    }

    score
}

